import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"ADR-0037: Plugin Resolution and Excludes","description":"","frontmatter":{},"headers":[],"relativePath":"handl/project/adrs/0037-plugin-resolution-and-excludes.md","filePath":"vendored/handl/project/adrs/0037-plugin-resolution-and-excludes.md"}`),a={name:`handl/project/adrs/0037-plugin-resolution-and-excludes.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0037-plugin-resolution-and-excludes" tabindex="-1">ADR-0037: Plugin Resolution and Excludes <a class="header-anchor" href="#adr-0037-plugin-resolution-and-excludes" aria-label="Permalink to “ADR-0037: Plugin Resolution and Excludes”">​</a></h1><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to “Status”">​</a></h2><p>Proposed</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p><code>HostConfig.excludes</code> is parsed from <code>.handl.toml</code> but never applied. A user can write:</p><div class="language-toml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">excludes </span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">=</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;"> [</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;">&quot;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;">some.plugin.id</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;">&quot;</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">]</span></span></code></pre></div><p>and the plugin is still loaded and active.</p><p>Additionally, <code>PluginRegistry::resolve</code> silently picks the last-registered plugin for a capability when multiple plugins provide it. There is no runtime conflict detection. The <code>resolve.rs</code> module has a full manifest-level resolver (<code>resolve()</code>) that handles exclusive capabilities, version matching, and conflict declarations, but it operates on <code>PluginManifest</code> slices and is not wired into the host loading flow.</p><p>This leaves three gaps:</p><ol><li>Excludes are ignored.</li><li>Capability conflicts are silent.</li><li>The manifest resolver and the runtime registry are disconnected.</li></ol><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><h3 id="_1-excludes-are-applied-by-the-applier-after-loading" tabindex="-1">1. Excludes are applied by the applier after loading <a class="header-anchor" href="#_1-excludes-are-applied-by-the-applier-after-loading" aria-label="Permalink to “1. Excludes are applied by the applier after loading”">​</a></h3><p><code>DefaultApplierPlugin::contribute</code> will, after loading kits and plugin manifests, remove any plugin whose id matches an entry in <code>config.excludes</code>. This requires <code>PluginRegistry::remove_by_id</code>.</p><p>Per-kit excludes (<code>KitReference.exclude</code>) are handled the same way — the applier collects them and removes matching plugins after the kit is loaded.</p><h3 id="_2-conflict-detection-is-a-host-method-not-a-capability" tabindex="-1">2. Conflict detection is a host method, not a capability <a class="header-anchor" href="#_2-conflict-detection-is-a-host-method-not-a-capability" aria-label="Permalink to “2. Conflict detection is a host method, not a capability”">​</a></h3><p><code>DefaultHost</code> gains a <code>resolve(&amp;self) -&gt; Result&lt;ResolvedComposition, ResolutionError&gt;</code> method that:</p><ul><li>Collects <code>PluginManifest</code>-like data from the live registry (id, version, capabilities, requires, conflicts, exclusive).</li><li>Calls <code>resolve::resolve()</code> with the collected manifests.</li><li>Returns the resolved composition or an error.</li></ul><p>This does not modify the registry. It is a validation step that the CLI or tests can call after <code>host.load()</code> to detect conflicts before running commands.</p><h3 id="_3-the-applier-does-not-auto-resolve" tabindex="-1">3. The applier does not auto-resolve <a class="header-anchor" href="#_3-the-applier-does-not-auto-resolve" aria-label="Permalink to “3. The applier does not auto-resolve”">​</a></h3><p>The applier loads and excludes. It does not call <code>host.resolve()</code>. Conflict detection is explicit, not implicit. This keeps loading fast and avoids surprising failures when multiple providers are intentional (e.g., during development).</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li><code>PluginRegistry</code> gains <code>remove_by_id</code>.</li><li><code>DefaultHost</code> gains <code>resolve</code>.</li><li><code>.handl.toml</code> <code>excludes</code> and per-kit <code>exclude</code> entries are now enforced.</li><li>Conflict detection is opt-in via <code>host.resolve()</code>.</li><li>The manifest resolver (<code>resolve.rs</code>) is reused, not replaced.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to “References”">​</a></h2><ul><li>ADR-0034: Zero-Monolith Plugin-Driven Platform</li><li>ADR-0035: Loaders as Abstract Plugins</li><li>ADR-0036: Host Applier as a Plugin</li></ul>`,24)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};